Method.Implementation:
	set pResponse=##class(IHC.ITF.ITFCOMMON.DataStructure.ExtractEncounterCMS).%New()

	Set tSC = ..CallStoredProc("ExtractEncounter_CMS", 52, req, .tOutParms)
	if $$$ISOK(tSC)
  	{
		Do ..CopyEncounterOutput(req.EncounterID, pResponse, tOutParms)
  	}
  	return tSC

	set pResponse=##class(IHC.ITF.ITFCOMMON.DataStructure.ExtractPatientCMS).%New()

