	set pResponse=##class(IHC.ITF.ITFCOMMON.DataStructure.ExtractPersonCMS).%New()

	Set tSC = ..CallStoredProc("ExtractPerson_CMS", 121, req, .tOutParms)
	if $$$ISOK(tSC)
  	{
		Do ..CopyPersonOutput(req.EncounterID, pResponse, tOutParms)
		if ($L(pResponse.ExtractPersonCMSRaceDE) > 0)
		{
			Do ..CallQuery("Select EntryCode from Race_DE where ID = " _ pResponse.ExtractPersonCMSRaceDE, .resStr)
			set pResponse.RaceEntryCode	= resStr
		}
		if ($L(pResponse.ExtractPersonCMSReligionDE) > 0)
		{
			Do ..CallQuery("Select EntryCode from Religion_DE where ID = " _ pResponse.ExtractPersonCMSReligionDE, .resStr)
			set pResponse.ReligionEntryCode	= resStr
		}

		if ($L(pResponse.ExtractPersonCMSPrimaryLanguageDE) > 0)
		{
			Do ..CallQuery("Select EntryCode from Language_DE where ID = " _ pResponse.ExtractPersonCMSPrimaryLanguageDE, .resStr)
			set pResponse.PRILanguageEntryCode	= resStr
		}
  	}
  	return tSC

