	set pResponse=##class(IHC.ITF.ITFCOMMON.DataStructure.ExtractChargeCMS).%New()

	Set tSC = ..CallStoredProc("ExtractCharge_CMS", 413, req, .tOutParms)
	if $$$ISOK(tSC)
  	{
		Do ..CopyExtractChargeCMS(req.EncounterID, pResponse, tOutParms)

		if ($L(pResponse.ExtractChargeCMSBillingProviderID) > 0)
		{
			Do ..CallQuery("Select EntryCode from Provider where ID = " _ pResponse.ExtractChargeCMSBillingProviderID, .resStr)
			set pResponse.ProviderID	= resStr
		}
		if ($L(pResponse.ExtractChargeCMSBillingReferProviderID)> 0)
		{
			Do ..CallQuery("SELECT EntryCode FROM Provider WHERE ID = " _ pResponse.ExtractChargeCMSBillingReferProviderID, .resStr)
			set pResponse.ReferProviderID	= resStr
		}


		if ($L(pResponse.ExtractChargeCMSOtherProviderID)> 0)
		{
			Do ..CallQuery("SELECT EntryCode FROM Provider WHERE ID = " _ pResponse.ExtractChargeCMSOtherProviderID, .resStr)
			set pResponse.OtherProviderIDEntryCode	= resStr
		}
  	}
  	return tSC

